220	  // START, not from the 05 start, so reshaping the 05 river (which changes its arc length) never slides the
221	  // 06/07 rings, lids or slot rows along the tube. The phases reproduce the pre-wave-6 layout exactly
222	  // (measured on that course: first 06/07 ring 5.5644 u after the 06 start; slot-row phase 0.96618 there).
223	  const s06 = course.stage('06').s0;
224	  const RING06_PHASE = 5.5643876;
225	  const ROW06_PHASE = 0.9661842;
226	  const rowRepeat0607 = slotRowsPerBay / ringSpacing;
227	  const rowOffset0607 = (((ROW06_PHASE - s06 * rowRepeat0607) % 1) + 1) % 1;
228	  const perfTubeMat = perforatedMetal({ ...wallBase, repeatV: rowRepeat0607, offsetV: rowOffset0607, slotHalf: [0.36, 0.12] });
229	  withTubeStrips(perfTubeMat, strips, 'attribute', 'wall');
230	  // straight-axis tunnel (05 → 07 incl. arch + plunge); the stream winds inside it
231	  const perfPath = straightTubePath(course, s05, s08, { window: 30, taper: 14, baseRadius: tubeR });
232	
233	  // ---- 05 current (ref 05): long ring bays + forced-perspective far tunnel, anchored to the 05 camera ----
234	  // Ref 05 ring radii about the VP: 288,192,122,85,66,54,45 px → from the locked checkpoint eye the rings sit
235	  // at depth ≈36/55 (near bays ≈17–19 units) and then recede in ever longer bays to a small warm light.
236	  // The straight only runs ≈56 units ahead of that eye before it flares into the 06 hall, so the real bays
237	  // end with a ring at depth ≈54 (sF05) and a ForcedTunnel (tube.ts) continues the same tunnel — walls,
238	  // slot rows, rings, lid pairs, water — to a virtual depth ≈430, compressed along the eye rays into the
239	  // last ≈6 real units. If path-camera moves the checkpoint, the bays and the far section follow.
240	  const sCam05 = course.marks['05_crest'] - (STAGE_CAM['05']?.back ?? 6.4);
241	  const bay05 = 14;
242	  const sGlow05 = course.stage('06').s0 - 5.9; // the straight flares into the 06 hall after this
