508	      if (x <= k[i][a] || i === k.length - 1) {
509	        const t = (x - k[i - 1][a]) / (k[i][a] - k[i - 1][a]);
510	        return k[i - 1][b] + t * (k[i][b] - k[i - 1][b]);
