608	  /**
609	   * The virtual tunnel's water surface: a flat chord across the section at `level` (relative to the tube
610	   * centre, along U) — uv.x 0..1 across, uv.y = sF + u. Because the section is a depth compression along
611	   * eye rays, this chord sits exactly on the real stream at the section start and rises above it further
612	   * in, so it takes over from the real water ribbon without a seam. Morph "open": dropped below the
613	   * real tube bottom.
614	   */
615	  chordGeometry(level: number, cols = 12, steps = 64, widthFrac = 1): THREE.BufferGeometry {
616	    const rows = steps + 1;
617	    const n = rows * (cols + 1);
618	    const pos = new Float32Array(n * 3), nor = new Float32Array(n * 3), uv = new Float32Array(n * 2);
619	    const ext = new Float32Array(n), opn = new Float32Array(n * 3);
620	    const o = new THREE.Vector3(), p = new THREE.Vector3(), cr = new THREE.Vector3();
621	    const w = Math.sqrt(Math.max(0, this.R * this.R - level * level)) * 0.995 * widthFrac;
622	    for (let i = 0; i < rows; i++) {
623	      const t = i / steps;
624	      const Dv = 1 / (1 / this.D0 - t * (1 / this.D0 - 1 / (this.D0 + this.zEnd)));
625	      const Z = Math.max(0, Dv - this.D0);
626	      const z = this.zOf(Z);
627	      const sReal = this.sF + z;
628	      const fr = this.path.frame(sReal);
629	      tubeCenterAt(this.path, sReal, cr);
630	      const rr = this.path.radius(sReal);
631	      for (let j = 0; j <= cols; j++) {
632	        const x = (j / cols * 2 - 1) * w;
633	        o.copy(this.Rt).multiplyScalar(x).addScaledVector(this.U, level);
634	        this.point(Z, o, p);
635	        const k = i * (cols + 1) + j;
636	        p.toArray(pos, k * 3);
637	        this.U.toArray(nor, k * 3);
638	        uv[k * 2] = j / cols; uv[k * 2 + 1] = this.sF + this.uOfZ(Z);
639	        ext[k] = Z - z;
640	        o.copy(cr).addScaledVector(fr.right, x * (rr / this.R)).addScaledVector(fr.up, -rr - 0.6);
641	        o.toArray(opn, k * 3);
642	      }
643	    }
644	    const idx: number[] = [];
645	    for (let i = 0; i < rows - 1; i++) {
646	      for (let j = 0; j < cols; j++) {
647	        const a = i * (cols + 1) + j, b = a + cols + 1;
648	        idx.push(a, a + 1, b, b, a + 1, b + 1);
649	      }
650	    }
651	    const g = new THREE.BufferGeometry();
652	    g.setAttribute('position', new THREE.BufferAttribute(pos, 3));
653	    g.setAttribute('normal', new THREE.BufferAttribute(nor, 3));
654	    g.setAttribute('uv', new THREE.BufferAttribute(uv, 2));
655	    g.setAttribute('fgExtra', new THREE.BufferAttribute(ext, 1));
656	    g.morphAttributes.position = [new THREE.BufferAttribute(opn, 3)];
