662	  /**
663	   * Lay instanced objects (rings, lids) into the virtual tunnel: item at tunnel coordinate `u`, offset `o`
664	   * from the centre line, rotation `basis` (local Z must run along the tube), scale `s`; when open they move
665	   * to `openPos` with in-plane scale `openScale`. Writes the instance matrices and the per-instance
666	   * `fgExtra` (virtual − real depth) the FG_VIRTUAL glow reads.
667	   */
668	  placeInstances(mesh: THREE.InstancedMesh, items: { u: number; o: THREE.Vector3; basis: THREE.Matrix4; s: THREE.Vector3; openPos: THREE.Vector3; openScale: number }[], open: number) {
669	    const m = new THREE.Matrix4();
670	    let ext = mesh.geometry.getAttribute('fgExtra') as THREE.InstancedBufferAttribute | undefined;
671	    if (!ext || ext.count < items.length) {
672	      ext = new THREE.InstancedBufferAttribute(new Float32Array(Math.max(1, items.length)), 1);
