/**
 * Third-person ride camera: behind/above Benny, looking along his heading (the course tangent), or
 * along the straight tunnel axis inside the 05–07 tube so the gold rings converge to one vanishing point
 * as in the references. Pitch & roll follow the banked path smoothly — including the 07 plunge.
 */
import * as THREE from 'three';
import { WORLD } from '../world/course';
import type { Course, StageId } from '../world/course';
import type { TubePath } from '../world/tube';

export interface CamParams {
  back: number; // distance behind Benny
  up: number; // height above Benny's water point
  ahead: number; // look-at distance ahead
  lookUp: number; // look-at height
  fov: number;
  latFollow: number; // 1 = camera fully follows Benny's lateral offset
  roll: number; // 0..1 how much of the path bank the camera adopts
  /** 05 only: view yaw (deg) to the LEFT of the tunnel axis, i.e. the vanishing point sits right of centre */
  yaw?: number;
  /** 05 only: lateral dead zone (units): the camera holds the tunnel axis while Benny is within ~this of it */
  deadZone?: number;
}

export const STAGE_CAM: Partial<Record<StageId, CamParams>> = {
  '03': { back: 6.5, up: 6.5, ahead: 6, lookUp: -1.5, fov: 64, latFollow: 0.3, roll: 0.3 },
  '04': { back: 8.5, up: 5.2, ahead: 14, lookUp: -3.0, fov: 66, latFollow: 0.6, roll: 0.4 },
  // 05: level rear chase down the straight current tube, camera ON the tunnel axis (rings concentric).
  // Ref 05 measured at vFOV 62: VP (498, 479) → view pitched atan((up-lookUp)/(ahead+back)) ≈ 12.7°
  // below and yawed ≈ 3° left of the axis; Benny's waterline 711 px below the VP → up/back ≈ 0.56.
  '05': { back: 6.4, up: 3.6, ahead: 18, lookUp: -1.92, fov: 62, latFollow: 0.85, roll: 0, yaw: 2.96, deadZone: 1.0 },
  '06': { back: 5.6, up: 2.6, ahead: 12, lookUp: 3.4, fov: 66, latFollow: 0.7, roll: 0.4 },
  '07': { back: 6.4, up: 4.1, ahead: 18, lookUp: 1.8, fov: 62, latFollow: 0.6, roll: 0.6 },
  '08': { back: 6.2, up: 3.7, ahead: 16, lookUp: 0.2, fov: 62, latFollow: 0.8, roll: 0.3 },
  '09': { back: 6.2, up: 3.7, ahead: 15, lookUp: 0.6, fov: 62, latFollow: 0.8, roll: 0.3 },
  '10': { back: 5.8, up: 3.4, ahead: 11, lookUp: 1.2, fov: 62, latFollow: 0.8, roll: 0.2 },
};

/** the blended (required) numeric keys; 05-only extras (yaw, deadZone) are read directly from STAGE_CAM */
type BlendKey = 'back' | 'up' | 'ahead' | 'lookUp' | 'fov' | 'latFollow' | 'roll';
const KEYS: BlendKey[] = ['back', 'up', 'ahead', 'lookUp', 'fov', 'latFollow', 'roll'];

export function camParamsAt(course: Course, s: number, blend = 8): CamParams {
  const acc: CamParams = { back: 0, up: 0, ahead: 0, lookUp: 0, fov: 0, latFollow: 0, roll: 0 };
  let w = 0;
  for (const st of course.stages) {
    const p = STAGE_CAM[st.id];
    if (!p) continue;
    const a = THREE.MathUtils.smoothstep(s, st.s0 - blend, st.s0 + blend) * (1 - THREE.MathUtils.smoothstep(s, st.s1 - blend, st.s1 + blend));
    if (a <= 0) continue;
    for (const k of KEYS) acc[k] += p[k] * a;
    w += a;
  }
  if (w === 0) return { ...(STAGE_CAM['03'] as CamParams) };
  for (const k of KEYS) acc[k] /= w;
  return acc;
}

export class RideCamera {
  readonly pos = new THREE.Vector3();
  readonly target = new THREE.Vector3();
  readonly up = new THREE.Vector3(0, 1, 0);
  fov = 70;
  private init = false;
  /** optional straight tunnel axis + the s-range where the camera aligns to it */
  axis: { path: TubePath; s0: number; s1: number } | null = null;

  constructor(private course: Course) {}

  /** desired pose for Benny at (s, lateral) */
  desired(s: number, lat: number, outPos: THREE.Vector3, outTarget: THREE.Vector3, outUp: THREE.Vector3): CamParams {
    const p = camParamsAt(this.course, s);
    const f = this.course.sample(s);
    const fb = this.course.sample(Math.max(0, s - p.back * 0.5)); // smoothing of heading
    const dir = f.tan.clone().lerp(fb.tan, 0.35).normalize();
    let up = f.up.clone();
    if (this.axis) {
      const a = this.axis;
      const w = THREE.MathUtils.smoothstep(s, a.s0, a.s0 + 10) * (1 - THREE.MathUtils.smoothstep(s, a.s1 - 10, a.s1));
      if (w > 0) {

      if (cp.mode === 'outro') {
        startOutro();
        settle(Math.round((cp.t ?? 0) / (1 / 30)), 1 / 30);
      } else {
        // settle camera springs without moving Benny: run with speed frozen
        const s0 = st.s;
        for (let i = 0; i < 40; i++) { stepSim(1 / 60); st.s = s0; st.lat = cp.lat ?? 0; }
        rideCam.update(0, st.s, st.lat, camera, true);
      }
    }
    // deterministic reference counter for this checkpoint (see docs: live play counts real pickups)
    const refId = (id.slice(0, 2) as StageId);
    st.coins = course.stage(refId).refCoins || START_COINS;
    hud.setCoins(st.coins);
    hud.setHearts(5);
    render();
    dirty = false;
    return { stage: st.stage, s: st.s, y: benny.root.position.y };
  };

  const api = {
    ready: true,
    checkpoints: Object.keys(CHECKPOINTS),
    goto: gotoCheckpoint,
    run(v = true) { running = v; last = performance.now(); },
    unfreeze() { st.frozen = null; input.override = null; },
    setSteer(v: number | null) { input.override = v; },
    /** deterministic simulation: advance n steps of dt (no rendering needed) */
    step(n: number, dt = 1 / 60) { for (let i = 0; i < n; i++) stepSim(dt); return api.state(); },
    startRideAt(id: StageId = '03') {
      resetToIntro(); startRide(); st.s = course.stage(id).s0; coins.resetUntil(-1); st.coins = START_COINS; hud.setCoins(st.coins); st.log = [];
      return api.state();
    },
    state() {
      return { mode: st.mode, stage: st.stage, s: +st.s.toFixed(3), lat: +st.lat.toFixed(3), coins: st.coins, hearts: st.hearts, paused: st.paused, bennyY: +benny.root.position.y.toFixed(3), bennyVisible: benny.root.visible, cam: camera.position.toArray().map((x) => +x.toFixed(2)) };
    },
    log() { return st.log; },
    coinDefs() { return coins.defs.map((d, i) => ({ s: d.s, lat: d.lat, taken: coins.collected[i] === 1 })); },
    /** QA: on-screen centre (px) and diameter (px) of every untaken coin in front of the camera */
    coinScreen() {
      const mesh = coins.group.children[0] as THREE.InstancedMesh;
      const m = new THREE.Matrix4(), p = new THREE.Vector3(), q = new THREE.Quaternion(), sc = new THREE.Vector3();
      const W = renderer.domElement.clientWidth, H = renderer.domElement.clientHeight;
      camera.updateMatrixWorld();
      const right = new THREE.Vector3().setFromMatrixColumn(camera.matrixWorld, 0);
      const out: { i: number; x: number; y: number; d: number }[] = [];
      coins.defs.forEach((_, i) => {
        if (coins.collected[i]) return;
        mesh.getMatrixAt(i, m); m.decompose(p, q, sc);
        const c = p.clone().project(camera);
        if (c.z > 1 || c.z < -1) return;
        const e = p.clone().addScaledVector(right, 0.5 * sc.x).project(camera);
        const x = ((c.x + 1) / 2) * W, y = ((1 - c.y) / 2) * H;
        if (x < -50 || x > W + 50 || y < -50 || y > H + 50) return;
        out.push({ i, x: Math.round(x), y: Math.round(y), d: Math.round((e.x - c.x) * W) });
      });
      return out;
    },
    respawns() { return st.respawns; },
    /** QA (camera lock): the live render camera — world matrix (column-major), vertical fov, aspect, near/far */
    camera() {
      camera.updateMatrixWorld();
      const W = renderer.domElement.clientWidth, H = renderer.domElement.clientHeight;
      return { matrixWorld: camera.matrixWorld.toArray(), fov: camera.fov, aspect: camera.aspect, near: camera.near, far: camera.far, width: W, height: H, position: camera.position.toArray(), target: rideCam.target.toArray() };
    },
    /** debug: Benny's projected screen position (NDC -1..1, z<1 = in front of camera) */
    bennyScreen() {
      const v = benny.root.getWorldPosition(new THREE.Vector3()).project(camera);
      return { x: +v.x.toFixed(2), y: +v.y.toFixed(2), z: +v.z.toFixed(3), visible: benny.root.visible, cam: camera.position.toArray().map((q) => +q.toFixed(2)), benny: benny.root.position.toArray().map((q) => +q.toFixed(2)) };
    },
    /** debug: what does a ray from the camera through NDC (x,y) hit first? */
    probe(x = 0, y = 0) {
      const rc = new THREE.Raycaster();
      rc.setFromCamera(new THREE.Vector2(x, y), camera);
      const hits = rc.intersectObjects(scene.children, true).filter((h) => (h.object as THREE.Mesh).isMesh && h.object.visible);
      const path = (o: THREE.Object3D) => { const a: string[] = []; let c: THREE.Object3D | null = o; while (c) { a.push(c.name || c.type); c = c.parent; } return a.slice(0, 5).join('<'); };
      return hits.slice(0, 4).map((h) => ({ d: +h.distance.toFixed(2), obj: path(h.object), p: h.point.toArray().map((v) => +v.toFixed(2)) }));
    },
    /** QA: which scene objects issue draw calls in one render ("parent/name" → calls), most first */
    drawList() {
      const hits = new Map<string, number>();
      const hooked: [THREE.Object3D, THREE.Object3D['onAfterRender']][] = [];
      scene.traverse((o) => {
        if (!(o as THREE.Mesh).isMesh && !(o as THREE.Points).isPoints && !(o as THREE.Line).isLine && !(o as THREE.Sprite).isSprite) return;
        const prev = o.onAfterRender;
        const key = (o.parent?.name ? o.parent.name + '/' : '') + (o.name || o.type);
        hooked.push([o, prev]);
        o.onAfterRender = (...a: Parameters<THREE.Object3D['onAfterRender']>) => { hits.set(key, (hits.get(key) ?? 0) + 1); prev.apply(o, a); };
      });
      render();
      for (const [o, prev] of hooked) o.onAfterRender = prev;
      return [...hits.entries()].sort((a, b) => b[1] - a[1]);
    },
    togglePause,
    stats() {
      const i = renderer.info;
      return { fps: +fps.toFixed(1), calls: i.render.calls, triangles: i.render.triangles, geometries: i.memory.geometries, textures: i.memory.textures, modules: { ...moduleStatus }, courseLength: course.length };
    },
    course,
  };
  (window as unknown as { __rainbow: typeof api }).__rainbow = api;
  return api;
}

// Resolve the Playwright that is pre-installed in this environment (global node_modules),
// falling back to a local install. Chromium launch flags give WebGL2 via SwiftShader headless.
import { createRequire } from 'node:module';
import { execSync } from 'node:child_process';
import { join } from 'node:path';

export function loadPlaywright() {
  try {
    return createRequire(import.meta.url)('playwright');
  } catch {
    const root = execSync('npm root -g').toString().trim();
    return createRequire(join(root, 'noop.js'))('playwright');
  }
}

export const CHROMIUM_ARGS = ['--use-angle=swiftshader', '--enable-unsafe-swiftshader', '--ignore-gpu-blocklist'];

/** start a Vite dev server for the project and return { url, close } */
export async function startVite(port = 5199) {
  const { createServer } = await import('vite');
  const server = await createServer({ server: { port, strictPort: false, host: '127.0.0.1', hmr: false, watch: { ignored: ['**/*'] } }, logLevel: 'error' });
  await server.listen();
  const addr = server.resolvedUrls?.local?.[0] ?? `http://127.0.0.1:${port}/`;
  return { url: addr.replace(/\/$/, ''), close: () => server.close() };
}

export async function waitDone(page, timeoutMs = 180000) {
  await page.waitForFunction(() => window.__done === true, null, { timeout: timeoutMs });
  const err = await page.evaluate(() => window.__error);
  if (err) throw new Error(err);
}
