{
  float lat = vRivLat;                                   // units from the tunnel axis (+ right)
  float xB = vRivA.x, hw = vRivA.y, cL = vRivA.z, cR = vRivA.w;
  float wL = vRivB.x, wR = vRivB.y, core = vRivB.z;
